mapper.update:
UPDATE POSITIONS
SET LIFECYCLE_KEY = #{lifecycleKey},
    UPDATED_AT = #{updatedAt}
WHERE ID = #{positionId}

UPDATE POSITIONS
SET BROKER_ORDER_ID = #{brokerOrderId},
    UPDATED_AT = #{updatedAt}
WHERE ID = #{positionId}

mapper.select:
SELECT COUNT(*)
FROM ORDERS
WHERE IDEMPOTENCY_KEY = #{idempotencyKey}

mapper.update:
UPDATE ORDERS
SET POSITION_ID = #{positionId},
    LIFECYCLE_KEY = #{lifecycleKey},
    UPDATED_AT = #{updatedAt}
WHERE ID = #{orderId}
  AND (POSITION_ID IS NULL OR POSITION_ID = 0)

UPDATE ORDERS
SET ORDER_STATUS = #{orderStatus},
    ERROR_MESSAGE = #{errorMessage},
    UPDATED_AT = #{updatedAt}
WHERE ID = #{orderId}
  AND ORDER_STATUS IN ('ORDERING', 'REQUESTED', 'DRY_RUN', 'ACCEPTED', 'PARTIALLY_FILLED', 'RETRY_PENDING')

UPDATE ORDERS
SET BROKER_STATUS = #{brokerStatus},
    ERROR_MESSAGE = #{errorMessage},
    UPDATED_AT = #{updatedAt}
WHERE ID = #{orderId}
  AND ORDER_STATUS IN ('ACCEPTED', 'PARTIALLY_FILLED')

UPDATE STOCK_MASTER
SET LAST_SELECTED_AT = #{selectedAt},
    UPDATED_AT = #{selectedAt}
WHERE ID = #{id}
  AND TYPE = 'DOMESTIC'

UPDATE STOCK_MASTER
SET LAST_BUY_ATTEMPT_AT = #{attemptedAt},
    UPDATED_AT = #{attemptedAt}
WHERE SYMBOL = #{symbol}
  AND MARKET_CODE = #{marketCode}
  AND TYPE = 'DOMESTIC'

UPDATE STOCK_MASTER
SET CONSECUTIVE_FAILURES = CONSECUTIVE_FAILURES + 1,
    RETRY_AFTER = #{retryAfter},
    EXCLUDED_REASON = #{reason},
    UPDATED_AT = #{updatedAt}
WHERE SYMBOL = #{symbol}
  AND MARKET_CODE = #{marketCode}
  AND TYPE = 'DOMESTIC'

UPDATE STOCK_MASTER
SET LAST_BUY_SUCCESS_AT = #{successAt},
    CONSECUTIVE_FAILURES = 0,
    RETRY_AFTER = NULL,
    EXCLUDED_REASON = NULL,
    UPDATED_AT = #{successAt}
WHERE SYMBOL = #{symbol}
  AND MARKET_CODE = #{marketCode}
  AND TYPE = 'DOMESTIC'

mapper.select:
SELECT COUNT(*)
FROM STOCK_MASTER
WHERE TYPE = 'OVERSEAS'
  AND EXCHANGE_CODE = #{exchangeCode}
  AND CURRENCY_CODE = #{currencyCode}

SELECT COUNT(*)
FROM STOCK_MASTER
WHERE TYPE = 'OVERSEAS'
  AND EXCHANGE_CODE = #{exchangeCode}
  AND PRICE_EXCHANGE_CODE = #{priceExchangeCode}
  AND CURRENCY_CODE = #{currencyCode}
  AND ACTIVE = 'Y'
  AND TRADABLE = 'Y'
  AND FRACTIONAL_TRADABLE = 'YES'

